def combination_sum(candidates, target):
    candidates = sorted(candidates)
    result = []
    chosen = []

    def build(start, remaining):
        if remaining == 0:
            result.append(chosen[:])           # the target is reached exactly: store a copy
            return
        for i in range(start, len(candidates)):
            if candidates[i] > remaining:
                break                          # sorted: every later candidate is too big as well
            chosen.append(candidates[i])
            build(i, remaining - candidates[i])    # i, not i + 1: the same number may be used again
            chosen.pop()

    build(0, target)
    return result
